func fuzz() {
private struct DiagnosticFromError: DiagnosticMessage {
  let error: Error
  let severity: DiagnosticSeverity = ./*c*/error

  var message: String {
    return String(describing: error)
  }

  var diagnosticID: MessageID {
    .init(domain: "SwiftDiagnostics", id : "\(type(of: error))")
  }
}
}

